"use client"

import * as React from "react"
import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group"
import { Radio as RadioPrimitive } from "@base-ui/react/radio"

import { cn } from "@/lib/utils"

// Base UI className can be a state function; the wrappers feed it to cn(), so
// narrow it to a plain string (same treatment as the other ported files).
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const RadioGroup = React.forwardRef<
  HTMLDivElement,
  WithClassName<RadioGroupPrimitive.Props>
>(({ className, ...props }, ref) => {
  return (
    <RadioGroupPrimitive
      data-slot="radio-group"
      className={cn("grid gap-2", className)}
      {...props}
      ref={ref}
    />
  )
})
RadioGroup.displayName = "RadioGroup"

const RadioGroupItem = React.forwardRef<
  HTMLButtonElement,
  WithClassName<RadioPrimitive.Root.Props>
>(({ className, ...props }, ref) => {
  return (
    <RadioPrimitive.Root
      data-slot="radio-group-item"
      ref={ref}
      className={cn(
        "inline-flex items-center justify-center aspect-square h-5 w-5 rounded-full",
        "backdrop-blur-xl bg-white/[0.06]",
        "border border-white/[0.15]",
        "shadow-[inset_0_0_0.25rem_oklch(1_0_0/0.06)]",
        "transition-all duration-base",
        "hover:border-white/[0.25]",
        "focus:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-0",
        "data-disabled:cursor-not-allowed data-disabled:opacity-50",
        "data-checked:border-[oklch(1_0_0_/_0.2)]",
        "data-checked:shadow-[var(--shadow-pillow-primary)]",
        className
      )}
      {...props}
    >
      <RadioPrimitive.Indicator data-slot="radio-group-indicator" className="size-full flex items-center justify-center">
        <div className="h-2.5 w-2.5 rounded-full bg-primary shadow-[var(--shadow-pillow-primary)]" />
      </RadioPrimitive.Indicator>
    </RadioPrimitive.Root>
  )
})
RadioGroupItem.displayName = "RadioGroupItem"

export { RadioGroup, RadioGroupItem }
